import{_ as o,o as t,c as i,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Hotkeys Settings","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/hotkeys-page.md","filePath":"user-guide/settings/hotkeys-page.md","lastUpdated":1787586465000}'),l={name:"user-guide/settings/hotkeys-page.md"};function n(s,e,r,c,d,g){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="hotkeys-settings" tabindex="-1">Hotkeys Settings <a class="header-anchor" href="#hotkeys-settings" aria-label="Permalink to &quot;Hotkeys Settings&quot;">​</a></h1><p>The Hotkeys settings page centralizes management of global summon hotkeys, in-app navigation keys, plugin action shortcuts, and foreground process filtering rules. The top tabs include: <strong>Global</strong>, <strong>Plugin Actions</strong>, and <strong>Process Blacklist</strong>.</p><h2 id="_1-global" tabindex="-1">1. Global <a class="header-anchor" href="#_1-global" aria-label="Permalink to &quot;1. Global&quot;">​</a></h2><h3 id="global-hotkeys-group" tabindex="-1">Global Hotkeys Group <a class="header-anchor" href="#global-hotkeys-group" aria-label="Permalink to &quot;Global Hotkeys Group&quot;">​</a></h3><ul><li><strong>Show/Hide Quick Search</strong>: Dedicated key recording box. Supports <strong>double-tap mode</strong> (default double <code>Ctrl</code>, configurable to double <code>Alt</code> or <code>Shift</code>) as well as <strong>standard key combinations</strong> (e.g. <code>Alt+Space</code>, <code>Win+Space</code>).</li><li><strong>Respond when focused on full-screen applications</strong>: Checkbox (default disabled). When enabled, Lertaro responds to hotkeys even when an exclusive fullscreen game or media player is active; when disabled, keys are bypassed silently to protect gameplay.</li><li><strong>Quick Jump</strong>: Default <code>Ctrl+G</code>. In file dialogs, jumps immediately to the directory most recently browsed in supported file managers.</li></ul><h3 id="navigation-function-keys-group" tabindex="-1">Navigation &amp; Function Keys Group <a class="header-anchor" href="#navigation-function-keys-group" aria-label="Permalink to &quot;Navigation &amp; Function Keys Group&quot;">​</a></h3><p>Provides dedicated key recording controls accepting custom single keys or combinations:</p><ul><li><strong>Select Next / Previous Item</strong>: Default <code>Ctrl+N</code> / <code>Ctrl+P</code> (equivalent to <code>↓</code> / <code>↑</code>).</li><li><strong>Jump to Result Modifier</strong>: Default <code>Ctrl</code>, used with numbers <code>1</code>–<code>9</code> for instant activation.</li><li><strong>Open Action Menu</strong>: Default <code>Ctrl+O</code> (equivalent to <code>→</code>).</li><li><strong>Autocomplete from Selection</strong>: Default <code>Ctrl+Tab</code>.</li><li><strong>QuickLook Instant Preview</strong>: Default <code>Alt+P</code>.</li><li><strong>Previous / Next Search Term</strong>: Default <code>Alt+Up</code> / <code>Alt+Down</code>.</li><li><strong>Delete Search History Term</strong>: Default <code>Ctrl+Delete</code>.</li><li><strong>Open Full Window</strong>: Default <code>Ctrl+F</code>.</li><li><strong>Open LocalSend Window</strong>: Default <code>Ctrl+S</code>.</li><li><strong>Pin Window (Keep Visible)</strong>: Default <code>Ctrl+T</code>.</li><li><strong>Toggle Quick Panel</strong>: Default <code>Ctrl+F2</code>.</li></ul><h3 id="quick-navigation-mouse-triggers-group" tabindex="-1">Quick Navigation Mouse Triggers Group <a class="header-anchor" href="#quick-navigation-mouse-triggers-group" aria-label="Permalink to &quot;Quick Navigation Mouse Triggers Group&quot;">​</a></h3><ul><li><strong>Double-click left button on blank area</strong>: Checkbox (default enabled). Pops up the Quick Navigation menu on desktop or File Explorer empty spaces.</li><li><strong>Middle-click on blank area</strong>: Checkbox (default enabled). Pops up the Quick Navigation menu on desktop, File Explorer, or open/save file dialogs.</li></ul><h2 id="_2-plugin-actions" tabindex="-1">2. Plugin Actions <a class="header-anchor" href="#_2-plugin-actions" aria-label="Permalink to &quot;2. Plugin Actions&quot;">​</a></h2><p>All action shortcuts registered by plugins (e.g. Copy Full Path <code>Ctrl+Shift+C</code>, Cut <code>Ctrl+X</code>, Copy <code>Ctrl+C</code>, Paste <code>Ctrl+V</code>, Delete <code>Delete</code>, Permanent Delete <code>Shift+Delete</code>) are grouped here.</p><ul><li><strong>Categorized View</strong>: Neatly organized by the originating plugin.</li><li><strong>Rebindable</strong>: Each action includes its own key recording control.</li></ul><h2 id="_3-process-blacklist" tabindex="-1">3. Process Blacklist <a class="header-anchor" href="#_3-process-blacklist" aria-label="Permalink to &quot;3. Process Blacklist&quot;">​</a></h2><p>Configures silence rules for specific foreground applications. When a blacklisted process is focused, Lertaro bypasses all global hotkeys and mouse triggers without interception.</p><ul><li><strong>Case-Insensitive</strong>: Both <code>game.exe</code> and <code>game</code> are matched.</li><li><strong>Add Single Entry</strong>: Type the process name and click <strong>Add Process</strong>.</li><li><strong>Batch Editing</strong>: Click <strong>Generate Text</strong> to export current entries to multi-line text, or paste a list and click <strong>Apply to List</strong> for batch updates.</li><li><strong>File Dialog Exemption</strong>: Even if an application is blacklisted, its native file selection dialogs remain exempted, ensuring seamless Inline Search and Quick Navigation.</li></ul>',16)])])}const h=o(l,[["render",n]]);export{p as __pageData,h as default};
